def classify(W,orig):
    out=[]
    for h in range(4):
        A=W[:,h*256:(h+1)*256]; B=orig[:,h*256:(h+1)*256]
        db=np.linalg.norm(A-B); nb=max(np.linalg.norm(B),1e-12)
        if db<1e-7: typ='same'
        elif np.linalg.norm(A)<1e-7: typ='zero'
        else:
            # scale correlation along B
            a=A.ravel(); b=B.ravel(); c=float(a@b/(b@b)); resid=float(np.linalg.norm(a-c*b)/nb)
            typ='scale%.3f resid%.3f'%(c,resid)
        out.append(typ)
    return out
