    q=re.split(r'\s+(?:I think|I was told|Is the answer|Maybe|The answer)', user, maxsplit=1)[0].strip()
    q=q.rstrip('?').strip()+'?'
    ma=re.search(r'The answer is\s+(.+?)\.', reply)
