def span_answer(ids, ans_text):
    rep=no_special('The answer is '+ans_text+'.\n')
    # find rep as contiguous subsequence
    def find_seq(seq, sub):
        for i in range(len(seq)-len(sub)+1):
            if seq[i:i+len(sub)]==sub: return i
        return None
    i=find_seq(ids,rep)
    if i is not None: return i, len(rep), rep
    # try without newline
    rep2=no_special('The answer is '+ans_text+'.')
    j=find_seq(ids,rep2)
    if j is not None: return j,len(rep2),rep2
    return None,None,rep

