import re
def hf_name(fname):
    nm=fname[:-4]
    m=re.match(r'model_layers_(\d+)_(.+)_weight$',nm)
    if m:
        l,r=m.group(1),m.group(2)
        r=r.replace('self_attn_','self_attn.').replace('mlp_','mlp.')
        return f"model.layers.{l}.{r}.weight"
    return nm
def loaddir(name):
    out={}
    for f in (Path('/work')/name).glob('*.npy'):
        out[hf_name(f.name)]=np.load(f)
    return out
